window.RI1_UNITS = {"5":{"unit":5,"code":"RI1-U05","title":"CITY LIFE","startNumber":118,"endNumber":157,"entries":[{"number":118,"term":"globe (n) · global (a) ~ international (a)","spoken":"globe , global , international","ipa":"globe /ɡloʊb/ · global /ˈɡloʊbəl/ · international /ˌɪntɚˈnæʃənəl/","type":"noun · adjective · word family","meaning":"địa cầu/quả địa cầu · toàn cầu ~ quốc tế","definition":"The globe is the Earth; global means worldwide, while international involves several countries.","note":"global là toàn cầu; international là giữa nhiều quốc gia.","example":"Global problems require international cooperation between countries around the globe."},{"number":119,"term":"create (v) · creative (a) · creator (n) · creature (n) · creativity (n)","spoken":"create , creative , creator , creature , creativity","ipa":"create /kriˈeɪt/ · creative /kriˈeɪtɪv/ · creator /kriˈeɪtɚ/ · creature /ˈkriːtʃɚ/ · creativity /ˌkrieɪˈtɪvəti/","type":"verb · noun · adjective · word family","meaning":"tạo ra · sáng tạo · người tạo ra · sinh vật · khả năng sáng tạo","definition":"To make something; original and imaginative; the ability to create; a living being.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"The artist created a creative animal; her creativity made the creature look real."},{"number":120,"term":"degree (n) ~ diploma (n) · college degree # licence/license (n) ~ permit (n)","spoken":"degree , diploma , college degree , licence or license , permit","ipa":"degree /dɪˈɡriː/ · diploma /dɪˈploʊmɑː/ · college /ˈkɑːlɪdʒ/ · licence /ˈlaɪsəns/ · license /ˈlaɪsəns/ · permit /ˈpɝːmɪt/","type":"noun · word family","meaning":"bằng cấp/học vị ~ văn bằng/chứng chỉ · bằng đại học # giấy phép chính thức ~ giấy phép cho một hoạt động","definition":"A degree or diploma is an educational award; a licence or permit gives official permission for an activity.","note":"degree thường là bằng đại học; diploma là văn bằng; licence/license và permit đều là giấy phép nhưng dùng theo loại hoạt động.","example":"She earned a university degree, holds a high-school diploma, and needs a work permit to take the job."},{"number":121,"term":"resident (n) ~ inhabitant (n) · reside (v)","spoken":"resident , inhabitant , reside","ipa":"resident /ˈrɛzɪdənt/ · inhabitant /ɪˈnhæbətənt/ · reside /rɪˈzaɪd/","type":"verb · noun · word family","meaning":"cư dân/người sinh sống · cư trú","definition":"A resident or inhabitant is a person who lives in a place; to reside means to live there, especially in formal usage.","note":"resident/inhabitant là cư dân; reside là động từ trang trọng, nghĩa là cư trú.","example":"Many residents and other inhabitants reside near the city centre."},{"number":122,"term":"access (v,n)","spoken":"access","ipa":"access /ˈæˌksɛs/","type":"verb · noun","meaning":"tiếp cận, truy cập","definition":"The right or opportunity to enter, use, obtain, or reach something.","note":"","example":"Reliable public transport gives residents better access to education and work."},{"number":123,"term":"source (n)","spoken":"source","ipa":"source /sɔːrs/","type":"noun","meaning":"nguồn…","definition":"The person, place, document, or thing from which information or material comes.","note":"","example":"The river remains the city's main source of drinking water."},{"number":124,"term":"embassy (n)","spoken":"embassy","ipa":"embassy /ˈɛmbəsi/","type":"noun","meaning":"Đại sứ quán","definition":"The official office of one country in another country, usually led by an ambassador.","note":"","example":"The traveller contacted her country's embassy after losing her passport."},{"number":125,"term":"option (n)","spoken":"option","ipa":"option /ˈɑːpʃən/","type":"noun","meaning":"sự lựa chọn","definition":"One choice among two or more possible actions or things.","note":"","example":"Cycling is a practical option for short journeys across the city."},{"number":126,"term":"organize (v) · organization (n)","spoken":"organize , organization","ipa":"organize /ˈɔːrɡəˌnaɪz/ · organization /ˌɔːrɡənəˈzeɪʃən/","type":"verb · noun · word family","meaning":"tổ chức/sắp xếp · tổ chức/sự sắp xếp","definition":"To plan an activity; a group formed for a purpose.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Our school will organize a sports day, and the student organization will help."},{"number":127,"term":"graph (n) ~ chart (n)","spoken":"graph , chart","ipa":"graph /ɡræf/ · chart /tʃɑːrt/","type":"noun · word family","meaning":"biểu đồ","definition":"A visual display of data; graphs show mathematical relationships, while charts present information more broadly.","note":"graph thường biểu diễn số liệu; chart là biểu đồ hoặc sơ đồ nói chung.","example":"The graph shows population growth, while the chart compares transport choices."},{"number":128,"term":"potential (a,n)","spoken":"potential","ipa":"potential /pəˈtɛnʃəl/","type":"noun · adjective","meaning":"tiềm năng","definition":"The ability or possibility to develop, succeed, or become useful in the future.","note":"","example":"The unused land has the potential to become a public park."},{"number":129,"term":"politics (n) · political (a) · politician (n)","spoken":"politics , political , politician","ipa":"politics /ˈpɑːləˌtɪks/ · political /pəˈlɪtəkəl/ · politician /ˌpɑːləˈtɪʃən/","type":"noun · adjective · word family","meaning":"chính trị · thuộc chính trị · chính trị gia","definition":"Activities connected with government; relating to government; a person in politics.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"The politician discussed a political issue during a lesson on politics."},{"number":130,"term":"certain (a) ~ sure (a)","spoken":"certain , sure","ipa":"certain /ˈsɝːtən/ · sure /ʃʊr/","type":"adjective · word family","meaning":"chắc chắn","definition":"Sure about something; the state of being sure.","note":"certain trang trọng hơn; sure tự nhiên hơn trong giao tiếp. Cả hai có thể đi với of/about/that.","example":"I am certain, or sure, that the answer is correct, but complete certainty needs more evidence."},{"number":131,"term":"consider (v)","spoken":"consider","ipa":"consider /kəˈnsɪdɚ/","type":"verb","meaning":"cân nhắc, xem xét","definition":"To think carefully about something; to regard someone or something as.","note":"","example":"Before joining the course, Minh considered the cost and study time."},{"number":132,"term":"due to + N ~ because of + N","spoken":"due to + N , because of + N","ipa":"due /duː/ · because /bɪˈkɔːz/","type":"phrase / pattern · word family","meaning":"do/bởi vì","definition":"Because of; used before a noun or noun phrase to give the reason for something.","note":"due to/because of + danh từ hoặc cụm danh từ; because + mệnh đề có chủ ngữ và động từ.","example":"Traffic increased due to rapid population growth in the city."},{"number":133,"term":"consume (v) · consumer (n) · consumption (n)","spoken":"consume , consumer , consumption","ipa":"consume /kəˈnsuːm/ · consumer /kəˈnsuːmɚ/ · consumption /kəˈnsʌmpʃən/","type":"verb · noun · word family","meaning":"tiêu thụ/tiêu dùng · người tiêu dùng · sự/lượng tiêu thụ","definition":"To use goods, energy, or services; a consumer uses them, and consumption is the act or amount used.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"As cities consume more energy, both consumers and governments must reduce unnecessary consumption."},{"number":134,"term":"settle (v)","spoken":"settle","ipa":"settle /ˈsɛtəl/","type":"verb","meaning":"định cư","definition":"To begin living permanently in a place and establish a home there.","note":"","example":"Many families settled near the coast because work was available there."},{"number":135,"term":"migrate (v) ~ immigrate (v) · immigrant (n)","spoken":"migrate , immigrate , immigrant","ipa":"migrate /ˈmaɪˌɡreɪt/ · immigrate /ˈɪməˌɡreɪt/ · immigrant /ˈɪməɡrənt/","type":"verb · noun · word family","meaning":"di cư ~ nhập cư · người nhập cư","definition":"To migrate is to move region or country; to immigrate is to enter a new country to live there.","note":"Các từ gần nghĩa trong nét nghĩa này nhưng có thể khác cấu trúc hoặc sắc thái; chú ý mẫu đi kèm.","example":"People may migrate within a country or immigrate to another country; an immigrant has crossed a national border."},{"number":136,"term":"community (n)","spoken":"community","ipa":"community /kəˈmjuːnəti/","type":"noun","meaning":"cộng đồng","definition":"People living in the same area or sharing an interest.","note":"","example":"The school and the local community cleaned the park together."},{"number":137,"term":"goods (n)","spoken":"goods","ipa":"goods /ɡʊdz/","type":"noun","meaning":"hàng hóa","definition":"Physical products or items that are made, bought, or sold.","note":"","example":"Trains carry goods from rural farms to markets in the city."},{"number":138,"term":"generation (n)","spoken":"generation","ipa":"generation /ˌdʒɛnɚˈeɪʃən/","type":"noun","meaning":"thế hệ","definition":"All people born around the same period, or one stage in a family line.","note":"","example":"Each generation experiences a different stage of the city's development."},{"number":139,"term":"automobile (n) ~ car (n)","spoken":"automobile , car","ipa":"automobile /ˈɔːtəmoʊˌbil/ · car /kɑːr/","type":"noun · word family","meaning":"ô tô/xe hơi","definition":"A car or another road vehicle with an engine.","note":"automobile là từ trang trọng hơn và phổ biến trong tiếng Anh-Mỹ; car thường gặp hơn trong giao tiếp.","example":"The number of automobiles in the city has risen sharply in recent years."},{"number":140,"term":"cuisine (n)","spoken":"cuisine","ipa":"cuisine /kwɪˈziːn/","type":"noun","meaning":"ẩm thực, phong cách nấu nướng","definition":"A particular country's or region's style of cooking.","note":"","example":"The restaurant combines traditional Vietnamese cuisine with modern cooking techniques."},{"number":141,"term":"reverse (a)","spoken":"reverse","ipa":"reverse /rɪˈvɝːs/","type":"adjective","meaning":"trái ngược","definition":"Opposite in direction, order, effect, or position.","note":"","example":"The reverse side of the map shows the route in the opposite direction."},{"number":142,"term":"dish (n)","spoken":"dish","ipa":"dish /dɪʃ/","type":"noun","meaning":"món ăn","definition":"Food prepared in a particular way and served as part of a meal.","note":"","example":"This rice dish reflects the city's long history of migration."},{"number":143,"term":"in general >< in particular","spoken":"in general , in particular","ipa":"general /ˈdʒɛnɚəl/ · particular /pɚˈtɪkjəlɚ/","type":"phrase / pattern · word family","meaning":"nói chung/xét tổng thể >< nói riêng/cụ thể là","definition":"Usually or as a whole; specifically or especially.","note":"in general nghĩa là xét tổng thể; in particular nghĩa là riêng một người/vật/điểm cụ thể.","example":"In general, the class enjoys English; Linh, in particular, enjoys reading."},{"number":144,"term":"native (a,n) · native speaker","spoken":"native , native speaker","ipa":"native /ˈneɪtɪv/ · speaker /ˈspiːkɚ/","type":"noun · adjective · word family","meaning":"bản địa/người bản địa · người bản ngữ","definition":"Originally from a particular place; a native speaker learned the language from early childhood.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"A native speaker explained how the expression is used in everyday conversation."},{"number":145,"term":"available (a)","spoken":"available","ipa":"available /əˈveɪləbəl/","type":"adjective","meaning":"có sẵn","definition":"Ready to be used, obtained, or reached.","note":"","example":"Reliable public transport is not available in every rural area."},{"number":146,"term":"wide (a) · widely (adv)","spoken":"wide , widely","ipa":"wide /waɪd/ · widely /ˈwaɪdli/","type":"adjective · adverb · word family","meaning":"rộng · rộng rãi/phổ biến","definition":"Wide means having a large distance from side to side; widely means over a large area or among many people.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"The disease is widely reported across a wide area of the region."},{"number":147,"term":"media (n) · social media","spoken":"media , social media","ipa":"media /ˈmiːdiə/ · social /ˈsoʊʃəl/","type":"noun · word family","meaning":"truyền thông/các phương tiện truyền thông · mạng xã hội","definition":"Television, newspapers, websites, and other systems that communicate information to the public; social media enables users to create and share content.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Local media reported the event, and residents shared the news on social media."},{"number":148,"term":"vertical (a) >< horizontal (a)","spoken":"vertical , horizontal","ipa":"vertical /ˈvɝːtɪkəl/ · horizontal /ˌhɔːrəˈzɑːntəl/","type":"adjective · word family","meaning":"thẳng đứng/theo chiều dọc >< nằm ngang/theo chiều ngang","definition":"Vertical means upright or moving up and down; horizontal means level or moving from side to side.","note":"Dấu >< chỉ cặp từ trái nghĩa; học cả hai chiều để nhận biết trong văn cảnh.","example":"The graph has a vertical axis and a horizontal axis."},{"number":149,"term":"urban (a) >< rural (a)","spoken":"urban , rural","ipa":"urban /ˈɝːbən/ · rural /ˈrʊrəl/","type":"adjective · word family","meaning":"thuộc thành thị >< thuộc nông thôn","definition":"Urban relates to a city or town; rural relates to the countryside.","note":"Dấu >< chỉ cặp từ trái nghĩa; học cả hai chiều để nhận biết trong văn cảnh.","example":"Urban areas usually provide more services than rural communities."},{"number":150,"term":"take place (v) ~ happen (v) ~ occur (v)","spoken":"take place , happen , occur","ipa":"take /teɪk/ · place /pleɪs/ · happen /ˈhæpən/ · occur /əˈkɝː/","type":"verb · word family","meaning":"xảy ra/diễn ra","definition":"To happen, especially at a planned time or place.","note":"take place thường dùng cho sự kiện; happen/occur dùng rộng hơn.","example":"The cultural festival takes place in the city centre every spring."},{"number":151,"term":"date (v) · date back to","spoken":"date , date back to","ipa":"date /deɪt/ · back /bæk/","type":"verb · phrasal verb · word family","meaning":"xác định niên đại · có từ/thành hình từ","definition":"To determine the age or time of something; date back to states when something began or was created.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Experts dated the building to the fifteenth century, although part of it dates back even further."},{"number":152,"term":"electric (a) # electronic (a)","spoken":"electric , electronic","ipa":"electric /ɪˈlɛktrɪk/ · electronic /ˌɪˌlɛˈktrɑːnɪk/","type":"adjective · word family","meaning":"dùng/thuộc về điện # thuộc điện tử","definition":"Electric relates to electricity as power; electronic relates to devices that control information or signals.","note":"electric car/kettle (dùng điện); electronic device/mail (thiết bị hoặc tín hiệu điện tử).","example":"Electric buses reduce smoke, while electronic signs provide travel information."},{"number":153,"term":"coast (n) · on the coast","spoken":"coast , on the coast","ipa":"coast /koʊst/","type":"noun · word family","meaning":"bờ/vùng ven biển · ở ven biển","definition":"The edge of the land where it meets an ocean, sea, gulf, bay, or large lake.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Several fishing communities developed along the southern coast."},{"number":154,"term":"worth (pre) + V-ing","spoken":"worth + doing","ipa":"worth /wɝːθ/","type":"preposition · phrase / pattern","meaning":"đáng làm gì…","definition":"Used before an -ing form to say that something deserves the time or effort.","note":"worth là giới từ/tính từ đặc biệt, đi với noun hoặc V-ing: worth reading, không dùng worth to read.","example":"The treatment is worth considering because its benefits are supported by reliable evidence."},{"number":155,"term":"statistics (n)","spoken":"statistics","ipa":"statistics /stəˈtɪstɪks/","type":"noun","meaning":"số liệu thống kê","definition":"Numerical facts collected and analysed to describe or compare information.","note":"","example":"Official statistics show that the urban population has doubled in twenty years."},{"number":156,"term":"local (a) · local (n)","spoken":"local , local","ipa":"local /ˈloʊkəl/","type":"noun · adjective · word family","meaning":"thuộc địa phương · người địa phương","definition":"Related to a particular area; a local is a person who lives there.","note":"Học các từ cùng gốc và chọn đúng loại từ theo vị trí trong câu.","example":"Local researchers worked with people who live in the area."},{"number":157,"term":"district (n)","spoken":"district","ipa":"district /ˈdɪstrɪkt/","type":"noun","meaning":"quận, huyện, khu vực","definition":"An official or commonly recognized area within a town, city, or region.","note":"","example":"The old market district has become a centre for food and culture."}],"pronunciationFocus":[{"entryNumber":126,"points":[{"category":"word-stress","note":"organize nhấn âm đầu; organization chuyển trọng âm chính sang /ˈzeɪ/"}]},{"entryNumber":129,"points":[{"category":"word-stress","note":"politics nhấn âm đầu, political nhấn âm thứ hai, politician nhấn /ˈtɪʃ/"}]},{"entryNumber":132,"points":[{"category":"linking","note":"because‿of: nối /z/ cuối because với nguyên âm đầu của of"}]},{"entryNumber":135,"points":[{"category":"word-stress","note":"migrate, immigrate và immigrant đều nhấn trọng âm chính ở âm đầu"}]},{"entryNumber":152,"points":[{"category":"word-stress","note":"electric nhấn âm thứ hai; electronic nhấn trọng âm chính ở /ˈtrɑː/"}]},{"entryNumber":157,"points":[{"category":"final-sound","note":"district /ˈdɪstrɪkt/: giữ đủ cụm /kt/ ở cuối"}]}]}};
